        }
        let schema=sqlite_snapshot::artifact::Reconstruction::new(control)?.text(document.text(1)?)?;
        control.checkpoint(Phase::ReconstructSnapshot,rows.len(),rows.len())?;
        Ok(Self{schema,pages:pages.take()})
    }
}

